SELECT COUNT(*) prose_stays,SUM(event) wording_deaths,SUM(standing) standing,SUM(raw_event-event) censored_removals,SUM(slot=0) slot_zero,SUM(slot<>max_slot) slot_changes_within_stay,SUM(author IS NULL) missing_author,SUM(duration=0) zero_duration,SUM(standing AND a<'2010-01-01')/SUM(standing)*100 before_2010_pct,SUM(standing AND a<'2015-01-01')/SUM(standing)*100 before_2015_pct,SUM(standing AND a<'2020-01-01')/SUM(standing)*100 before_2020_pct FROM facts WHERE kind='prose' ;
